list_categories.code:
response = client.categories.list_categories(
    {"limit": 10, "offset": 10, "sort": "name", "dir": "asc"}
)
for category in response.map["categories"]:
    print(category["id"], category["general"]["name"], category["general"]["url"])
print(response.map["pagination"]["total"], response.map["pagination"]["has_next"])

create_category.code:
response = client.categories.create_category({"category": {
    "general": {
        "name": "Seasonal Produce", "title": "Seasonal Produce", "heading": "Fresh this season",
        "summary": "Fruit and vegetables picked this week", "parent_category": {"id": 4310},
    },
    "description": {"content": "<p>What is in season right now.</p>"},
    "availability_visibility": {"visible": True, "custom_sorting": True, "default_sorting": "alpha_asc"},
    "tax_shipping": {"tax_message": "Prices include GST"},
    "assign_products": {"products": [101, 102]},
}})
category = response.map["category"]
print(category["id"], category["general"]["sku"], category["general"]["url"])

update_category.code:
response = client.categories.update_category(4321, {
    "category": {"general": {"name": "Seasonal Produce", "heading": "New heading"}},
})
general = response.map["category"]["general"]
print(general["name"], general["heading"], general["summary"])

patch_category.code:
response = client.categories.patch_category(4321, {
    "category": {
        "general": {"summary": "Updated summary"},
        "availability_visibility": {"visible": False},
    },
})
category = response.map["category"]
print(category["general"]["summary"], category["availability_visibility"]["visible"])

patch_category_section.code:
response = client.categories.patch_category_section(
    4321, "assign_products", {"category": {"assign_products": {"products": [101, 102, 103]}}}
)
for product in response.map["category"]["assign_products"]["products"]:
    print(product["id"], product["sku"], product["name"])
